const input=$json.body??$json;
const closeStatus=String(input.close_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const closeDate=String(input.actual_closing_date??input.closing_date??'').trim();
const gross=Number(input.gross_profit??0),costs=Number(input.closing_costs??0),net=Number(input.net_profit??(gross-costs));
const exitStrategy=String(input.exit_strategy??'assignment').trim();
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const profitValid=Number.isFinite(gross)&&Number.isFinite(costs)&&Number.isFinite(net);
let closeout_status='needs_review',next='WF-126',reason='CRM closeout requires review';
if(input.dnc===true){closeout_status='blocked_dnc';reason='DNC/contact restriction';}
else if(blockers.length){closeout_status='blocked';reason='active closeout blockers';}
else if(closeStatus!=='verified_close'){closeout_status='close_not_verified';next='WF-328';reason='verified close is not confirmed';}
else if(!dealId||!leadId||!propertyId){closeout_status='incomplete_identity';reason='deal/property/lead identity incomplete';}
else if(!closeDate){closeout_status='closing_date_missing';reason='actual closing date missing';}
else if(!profitValid){closeout_status='profit_inputs_invalid';reason='profit or closing cost inputs are invalid';}
else if(net<0){closeout_status='negative_profit_review';next='WF-330';reason='negative net profit requires review before portfolio closeout';}
else{closeout_status='closeout_ready';next='WF-330';reason='verified close and profit inputs are ready for final CRM closeout and assignment profit recording';}
const assignmentProfitRecord={deal_id:dealId,lead_id:leadId,property_id:propertyId,close_date:closeDate,gross_profit:gross,closing_costs:costs,net_profit:net,exit_strategy:exitStrategy,verified_close:true};
const portfolioFeedback={deal_id:dealId,net_profit:net,profit_margin:gross?net/gross:null,exit_strategy:exitStrategy,calibration_signal:net>0?'positive':'negative'};
return [{json:{...input,workflow_id:'WF-329',workflow_name:'Verified Close → Final CRM Closeout & Assignment Profit Record Controller',closeout_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,actual_closing_date:closeDate||null,gross_profit:gross,closing_costs:costs,net_profit:net,exit_strategy:exitStrategy,assignment_profit_record:assignmentProfitRecord,portfolio_feedback:portfolioFeedback,next_workflow:next,human_review_required:closeout_status!=='closeout_ready',crm_activity:{activity_type:'final_crm_closeout',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:closeout_status,closing_date:closeDate||null,gross_profit:gross,closing_costs:costs,net_profit:net,reason}}}];
